function check() {
   var initiatorVal = workflowData.getMetaDataMap().get("Initiator");
   log.info("requestedBy :" + initiatorVal);
    if (initiatorVal == "ToStudent"  || initiatorVal != "Initiator"  ) {
            return true;
    }
    else {
        return false;
    }
}

